import{_ as a,c as o,o as n,ag as r}from"./chunks/framework.CPHm90Yq.js";const c=JSON.parse('{"title":"Release Notes 2020","description":"","frontmatter":{},"headers":[],"relativePath":"changes/2020.md","filePath":"changes/2020.md"}'),i={name:"changes/2020.md"};function t(s,e,l,d,h,g){return n(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="release-notes-2020" tabindex="-1">Release Notes 2020 <a class="header-anchor" href="#release-notes-2020" aria-label="Permalink to &quot;Release Notes 2020&quot;">​</a></h1><h2 id="v1-5-x-july-2020" tabindex="-1">v1.5.x (July 2020) <a class="header-anchor" href="#v1-5-x-july-2020" aria-label="Permalink to &quot;v1.5.x (July 2020)&quot;">​</a></h2><p>Apart from some smaller bug-fixes and features, this release brings <strong>three major improvements</strong>:</p><ul><li>With the new <a href="https://argdown.org/guide/publishing-argdown-markdown-with-pandoc.html" target="_blank" rel="noreferrer">Pandoc filter</a> you can now publish Argdown-in-Markdown documents as pdf files.</li><li>The Pandoc filter and <code>@argdown/cli</code> can be extended by installing the new <code>@argdown/image-export</code> plugin that allows to <a href="https://github.com/christianvoigt/argdown/tree/master/packages/argdown-image-export/" target="_blank" rel="noreferrer">export maps to png, jpg and webp images</a>.</li><li>The VSCode extension now adds <a href="https://github.com/christianvoigt/argdown/tree/master/packages/argdown-vscode/README.md#configuration-files" target="_blank" rel="noreferrer">IntelliSense, validation, hover descriptions and quick navigation for <code>argdown.config.js</code> files</a> making it much easier to find your way through the file format and the many configuration options.</li></ul><h3 id="additional-features-bug-fixes" tabindex="-1">Additional features &amp; bug fixes <a class="header-anchor" href="#additional-features-bug-fixes" aria-label="Permalink to &quot;Additional features &amp; bug fixes&quot;">​</a></h3><ul><li>Using the command <code>argdown [input file glob]</code> you can check the validity of your Argdown files. <code>@argdown/cli</code> will return with errorCode 1 if there are any errors (closes <a href="https://github.com/christianvoigt/argdown/issues/167" target="_blank" rel="noreferrer">#167</a>).</li><li>In general, <code>@argdown/cli</code>&#39;s error handling and logging has been improved to give more feedback to the user. If you don&#39;t want the additional &quot;noise&quot;, use the new <code>--silent</code> flag.</li><li>You can now <a href="./.html">set the line width and arrow size</a> of edges in dot graphs (closes <a href="https://github.com/christianvoigt/argdown/issues/168" target="_blank" rel="noreferrer">#168</a>)</li><li>You can now <a href="https://argdown.org/guide/embedding-your-maps-in-a-webpage.html#styling-the-component" target="_blank" rel="noreferrer">customize the colors of the web-component</a> by using css variables.</li><li>VSCode&#39;s new API for webview resources has been adopted (closes <a href="https://github.com/christianvoigt/argdown/issues/160" target="_blank" rel="noreferrer">#160</a>).</li><li>The VSCode extension no longer fails to export files if no workspace is open (fixes <a href="https://github.com/christianvoigt/argdown/issues/159" target="_blank" rel="noreferrer">#159</a>).</li><li>Upgraded parser to <a href="https://github.com/SAP/chevrotain" target="_blank" rel="noreferrer">Chevrotain 7.0.1</a></li><li>Upgraded to <a href="https://github.com/aduh95/viz.js" target="_blank" rel="noreferrer">@aduh95/viz.js 3.1.0</a> in all packages using Viz.js</li></ul><p>As always, all package dependencies have been upgraded.</p><p>Thanks again to <a href="https://github.com/aduh95" target="_blank" rel="noreferrer">Antoine du Hamel</a> for his work on maintaining <a href="https://github.com/aduh95/viz.js" target="_blank" rel="noreferrer">@aduh95/viz.js</a>.</p><h3 id="patches" tabindex="-1">Patches <a class="header-anchor" href="#patches" aria-label="Permalink to &quot;Patches&quot;">​</a></h3><h4 id="_1-5-1" tabindex="-1">1.5.1 <a class="header-anchor" href="#_1-5-1" aria-label="Permalink to &quot;1.5.1&quot;">​</a></h4><ul><li><code>@argdown/cli</code>: Fixes missing <code>import-global</code> package (<a href="https://github.com/christianvoigt/argdown/issues/179" target="_blank" rel="noreferrer">#179</a>)</li></ul><h4 id="_1-5-2" tabindex="-1">1.5.2 <a class="header-anchor" href="#_1-5-2" aria-label="Permalink to &quot;1.5.2&quot;">​</a></h4><ul><li><code>@argdown/cli</code> &amp; <code>@argdown/node</code>: Fixes uncaught EExist error when running <code>argdown html</code> (<a href="https://github.com/christianvoigt/argdown/issues/180" target="_blank" rel="noreferrer">#180</a>)</li><li><code>@argdown/image-export</code>: fixes missing <code>@argdown/node</code> dependency (was only devDependency), (<a href="https://github.com/christianvoigt/argdown/issues/186" target="_blank" rel="noreferrer">#186</a>)</li><li><code>@argdown/pandoc-filter</code>: fixes typescript compilation of optional chaining, (<a href="https://github.com/christianvoigt/argdown/issues/186" target="_blank" rel="noreferrer">#187</a>)</li></ul><h3 id="_1-5-3" tabindex="-1">1.5.3 <a class="header-anchor" href="#_1-5-3" aria-label="Permalink to &quot;1.5.3&quot;">​</a></h3><ul><li><code>@argdown/node</code>, <code>@argdown/language-server</code>, <code>argdown-vscode</code>: Fixes svg/png export in VSCode by reverting to SyncDotToSvgExportPlugin (<a href="https://github.com/christianvoigt/argdown/issues/193" target="_blank" rel="noreferrer">#193</a>)</li><li><code>@argdown/language-server</code>, <code>argdown-vscode</code>: upgrade bundling configs to webpack 5</li></ul><h2 id="v1-4-x-april-2020" tabindex="-1">v1.4.x (April 2020) <a class="header-anchor" href="#v1-4-x-april-2020" aria-label="Permalink to &quot;v1.4.x (April 2020)&quot;">​</a></h2><p>This release is improving the Argdown workflow significantly: It is now possible to</p><ul><li>use <a href="#using-argdown-in-markdown">Argdown <em>within</em> Markdown</a> documents and export the whole document with Argdown web components to HTML</li><li>copy &amp; paste your argument map as <a href="#the-argdown-web-component">Argdown web component</a> into any web page</li><li><a href="#remark-markdown-it-and-marked-plugins">integrate Argdown</a> into <a href="https://www.staticgen.com/" target="_blank" rel="noreferrer">static site generators</a> and similar applications <em>by simply changing their Markdown parser configuration</em></li></ul><p>For a list of bug fixes in this release cycle, see the notes for the specific versions below the new feature sections.</p><p>The VSCode extension 1.4.x requires VSCode version &gt;= 1.43.0. Please update VSCode!</p><h3 id="using-argdown-in-markdown" tabindex="-1">Using Argdown in Markdown <a class="header-anchor" href="#using-argdown-in-markdown" aria-label="Permalink to &quot;Using Argdown in Markdown&quot;">​</a></h3><p>You can now use Argdown directly in Markdown documents by using code fences. Your Argdown code fences will be correctly highlighted.</p><p>If you open the Markdown preview, it will automatically replace the Argdown code fences with a web component showing the Viz.js argument map.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># A Markdown header</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Now comes the </span><span style="--shiki-light:#24292E;--shiki-light-font-style:italic;--shiki-dark:#E1E4E8;--shiki-dark-font-style:italic;">_Argdown_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> map:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`argdown</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">===</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">title: my argdown map</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">===</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[S]: Some statement</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;- &lt;A&gt;: Some argument</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Now we are back in Markdown.</span></span></code></pre></div><p>For more details read the guide on <a href="https://argdown.org/guide/using-argdown-in-markdown.html" target="_blank" rel="noreferrer">using Argdown in Markdown</a>.</p><h3 id="the-argdown-web-component" tabindex="-1">The Argdown Web Component <a class="header-anchor" href="#the-argdown-web-component" aria-label="Permalink to &quot;The Argdown Web Component&quot;">​</a></h3><p>The web component allows you to switch between a zoomable map and a syntax-highlighted source view, just like in the Argdown documentation (which from now on also uses the new web component).</p><p>Both the commandline tool and the VSCode extension provide a new &quot;web component&quot; export, that will wrap your source code and Viz.js map in a custom html element. By exporting your documents as web components you can &quot;copy &amp; paste&quot; them into any html document to embed your maps into your webpage.</p><p>In <code>@argdown/cli</code> use the new <code>argdown web-component [inputGlob] [outputFolder]</code> command to export your argdown file as web component html.</p><p>For more details on how to setup and configure the web component, read the guide on <a href="https://argdown.org/guide/embedding-your-maps-in-a-webpage.html" target="_blank" rel="noreferrer">how to embed your argument maps in a web page</a>.</p><h3 id="remark-markdown-it-and-marked-plugins" tabindex="-1">Remark, Markdown-It and Marked plugins <a class="header-anchor" href="#remark-markdown-it-and-marked-plugins" aria-label="Permalink to &quot;Remark, Markdown-It and Marked plugins&quot;">​</a></h3><p>If you want to export a complete Markdown document containing Argdown code fences to HTML you now have four options:</p><ul><li>use the new <code>argdown markdown [inputGlob] [outputFolder]</code> command of <code>@argdown/cli</code> (internally it uses markdown-it to parse the markdown)</li><li>use <a href="https://github.com/remarkjs/remark" target="_blank" rel="noreferrer">remark</a> together with <code>@argdown/remark-plugin</code> or use <code>@argdown/gatsby-remark-plugin</code> in <a href="https://www.gatsbyjs.org/" target="_blank" rel="noreferrer">Gatsby</a>.</li><li>use <a href="https://github.com/markdown-it/markdown-it" target="_blank" rel="noreferrer">markdown-it</a> together with <code>@argdown/markdown-it-plugin</code></li><li>use <a href="https://github.com/markedjs/marked" target="_blank" rel="noreferrer">marked</a> together with <code>@argdown/marked-plugin</code></li></ul><p>All of these exports will replace Argdown code fences with the Argdown web component just as the VSCode Markdown preview does (if you have installed the Argdown VSCode extension).</p><p>The Markdown parser plugins can be used to integrate Argdown support into any of the many applications that use these parsers, for example static site generators like <a href="https://www.gatsbyjs.org/" target="_blank" rel="noreferrer">Gatsby</a>, <a href="https://www.11ty.dev/" target="_blank" rel="noreferrer">Eleventy</a> or <a href="https://vuepress.vuejs.org/" target="_blank" rel="noreferrer">Vuepress</a>.</p><p>Read more about how to set this up in the guide on <a href="https://argdown.org/guide/integrating-argdown-markdown-into-applications.html" target="_blank" rel="noreferrer">how to integrate Argdown-Markdown into existing applications</a>.</p><h3 id="highlight-js-plugin" tabindex="-1">Highlight.js plugin <a class="header-anchor" href="#highlight-js-plugin" aria-label="Permalink to &quot;Highlight.js plugin&quot;">​</a></h3><p>This release also adds a <a href="https://github.com/highlightjs/highlight.js/" target="_blank" rel="noreferrer">highlight.js</a> plugin with Argdown language support. The plugin is used to add syntax highlighting in the web component export.</p><p>The plugin can also be used on its own, if you don&#39;t want to use the web component, but want to add syntax highlighting to Argdown source code.</p><p>For the same purpose you might also be interested in our old <a href="https://prismjs.com/" target="_blank" rel="noreferrer">prismjs</a> plugin in the Argdown repository.</p><h3 id="thanks" tabindex="-1">Thanks <a class="header-anchor" href="#thanks" aria-label="Permalink to &quot;Thanks&quot;">​</a></h3><p>Thanks to <a href="https://github.com/aduh95" target="_blank" rel="noreferrer">Antoine du Hamel</a> for creating and maintaining a new fork of <a href="https://github.com/aduh95/viz.js" target="_blank" rel="noreferrer">Viz.js</a> after the original repository was abandoned. Argdown is now using this new version in the web component export and will switch completely to it as soon as VSCode is based at least on node v13.</p><h3 id="detailed-fixes-changes" tabindex="-1">Detailed Fixes &amp; Changes <a class="header-anchor" href="#detailed-fixes-changes" aria-label="Permalink to &quot;Detailed Fixes &amp; Changes&quot;">​</a></h3><h4 id="v1-4-9" tabindex="-1">v1.4.9 <a class="header-anchor" href="#v1-4-9" aria-label="Permalink to &quot;v1.4.9&quot;">​</a></h4><ul><li>@argdown/core: fixed lodash.merge import #156</li></ul><h4 id="v1-4-8" tabindex="-1">v1.4.8 <a class="header-anchor" href="#v1-4-8" aria-label="Permalink to &quot;v1.4.8&quot;">​</a></h4><ul><li>@argdown/web-components: fixed map disappears on zoom in Firefox #155</li></ul><h4 id="v1-4-7" tabindex="-1">v1.4.7 <a class="header-anchor" href="#v1-4-7" aria-label="Permalink to &quot;v1.4.7&quot;">​</a></h4><ul><li>@argdown/core: fixed files property in package.json</li></ul><h4 id="v1-4-6" tabindex="-1">v1.4.6 <a class="header-anchor" href="#v1-4-6" aria-label="Permalink to &quot;v1.4.6&quot;">​</a></h4><p>everything finally released</p><ul><li>@argdown/sandbox: changes to webpack config, enabled treeshaking, reduced file size from 8mb to 2mb, finally ready for release on argdown.org</li><li>@argdown/core: fixed bold/italic ranges in argument labels</li><li>@argdown/core: reduced footprint by using highlightjs core and removing SyncDotToSvgExportPlugin from index (has to be imported explicitely now)</li><li>@argdown/node: reduced footprint by removing lodash dependency from AsyncArgdownApplication</li><li>@argdown/web-components: fixed check if slots are filled (did not work on argdown.org)</li></ul><h4 id="v1-4-5" tabindex="-1">v1.4.5 <a class="header-anchor" href="#v1-4-5" aria-label="Permalink to &quot;v1.4.5&quot;">​</a></h4><p>argdown-vscode released</p><p>docs &amp; sandbox not yet released because of build problems</p><ul><li>@argdown/language-server &amp; argdown-vscode: new build process, after many fixes (see below), webpack bundling is finally working, VSCode extension can now be released on store</li><li>@argdown/core: fixed WebComponentExportPlugin&#39;s web-component script loading</li></ul><h4 id="v1-4-4" tabindex="-1">v1.4.4 <a class="header-anchor" href="#v1-4-4" aria-label="Permalink to &quot;v1.4.4&quot;">​</a></h4><p>argdown-vscode, docs &amp; sandbox not yet released because of build problems</p><ul><li>@argdown/web-components: downgrading to parcel 1, to fix jsdelivr file urls (parcel 2 is to unstable and unpredictable right now)</li><li>@argdown/node: further clean up for bundling with webpack</li></ul><h4 id="v1-4-3" tabindex="-1">v1.4.3 <a class="header-anchor" href="#v1-4-3" aria-label="Permalink to &quot;v1.4.3&quot;">​</a></h4><p>argdown-vscode, docs &amp; sandbox not yet released because of build problems</p><ul><li>@argdown/node: changes to tsconfig, fixes problems with packing in @argdown/vscode</li><li>@argdown/node: better import of lodash functions</li><li>@argdown/web-components: trying to fix parcel 2 build process, using jsdelivr does not work right now</li></ul><h4 id="v1-4-2" tabindex="-1">v1.4.2 <a class="header-anchor" href="#v1-4-2" aria-label="Permalink to &quot;v1.4.2&quot;">​</a></h4><p>argdown-vscode, docs &amp; sandbox not yet released because of build problems</p><ul><li>@argdown/cli: fixes name in cli help from cli.js to argdown (yargs changed)</li></ul><h4 id="v1-4-1" tabindex="-1">v1.4.1 <a class="header-anchor" href="#v1-4-1" aria-label="Permalink to &quot;v1.4.1&quot;">​</a></h4><p>argdown-vscode, docs &amp; sandbox not yet released because of build problems</p><ul><li>@argdown/cli: fixes missing help in @argdown/cli</li><li>@argdown/markdown-it-plugin: fixes missing file load in @argdown/markdown-it-plugin</li><li>@argdown/web-components): fix build paths</li></ul><h4 id="v1-4-0" tabindex="-1">v1.4.0 <a class="header-anchor" href="#v1-4-0" aria-label="Permalink to &quot;v1.4.0&quot;">​</a></h4><p><strong>Changes in:</strong> @argdown/core, @argdown/node, argdown-vscode, @argdown/language-server, @argdown/sandbox, @argdown/codemirror-mode, docs</p><p><strong>New packages:</strong> @argdown/web-components, @argdown/remark-plugin, @argdown/gatsby-remark-plugin, @argdown/markdown-it-plugin, @argdown/marked-plugin, @argdown/highlightjs</p><p>argdown-vscode, docs &amp; sandbox not yet released because of build problems</p><ul><li>argdown-vscode: Argdown configuration files in your workspace folder are now used if you export your Argdown file into other formats (you can use the VSCode settings to set the filename of your config file)</li><li>#138: No italic in Viz.js map: Italic and bold ranges are now kind of supported in Viz.js and GraphML (not yet in Dagre): Graphviz rendering seems to be buggy in this respect, it will not display an empty space after an italic or bold range. As a workaround, an extra empty space is now added automatically, but this is a hack that might lead to problems in yEd or in the future if this bug is finally fixed. Link ranges are not supported at all in Graphviz (only tables and cells can have a href attribute).</li><li>#144: broken links custom shortcodes</li></ul><h2 id="older-releases" tabindex="-1">Older releases <a class="header-anchor" href="#older-releases" aria-label="Permalink to &quot;Older releases&quot;">​</a></h2><p>For the relase notes of 2019 visit <a href="https://argdown.org/changes/2019.html" target="_blank" rel="noreferrer">this page</a>.</p>`,75)])])}const u=a(i,[["render",t]]);export{c as __pageData,u as default};
